def name_operands(region,function_address,operation):
    if (region,function_address)!=('Action',0xF67F):return operation
    return (operation.replace('(IX+#10)','(IX + @FActionRecord.OffsetScaleLow)')
            .replace('#F691','@Action.ResetIdleRecordBases.Entry')
            .replace('CALL #F0F8','CALL @Action.PrepareObjectOffsetTransform.Entry'))
